{"metadata":{"kernelspec":{"language":"python","display_name":"Python 3","name":"python3"},"language_info":{"name":"python","version":"3.12.13","mimetype":"text/x-python","codemirror_mode":{"name":"ipython","version":3},"pygments_lexer":"ipython3","nbconvert_exporter":"python","file_extension":".py"},"kaggle":{"accelerator":"none","dataSources":[{"sourceType":"datasetVersion","sourceId":19096563}],"isInternetEnabled":true,"language":"python","sourceType":"script","isGpuEnabled":false}},"nbformat_minor":4,"nbformat":4,"cells":[{"cell_type":"code","source":"# %% [code] {\"jupyter\":{\"outputs_hidden\":false},\"execution\":{\"iopub.status.busy\":\"2026-08-27T07:02:36.542478Z\",\"iopub.execute_input\":\"2026-08-27T07:02:36.543859Z\",\"iopub.status.idle\":\"2026-08-27T07:02:37.819003Z\",\"shell.execute_reply.started\":\"2026-08-27T07:02:36.543771Z\",\"shell.execute_reply\":\"2026-08-27T07:02:37.817784Z\"}}\n!git clone https://github.com/Rhivu10/ClauseLens.git /kaggle/working/ClauseLens\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2026-08-27T07:02:39.745249Z\",\"iopub.execute_input\":\"2026-08-27T07:02:39.746255Z\",\"iopub.status.idle\":\"2026-08-27T07:02:40.250993Z\",\"shell.execute_reply.started\":\"2026-08-27T07:02:39.746185Z\",\"shell.execute_reply\":\"2026-08-27T07:02:40.249744Z\"}}\n%cd /kaggle/working/ClauseLens\n!git pull\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2026-08-27T07:02:40.384165Z\",\"iopub.execute_input\":\"2026-08-27T07:02:40.384688Z\",\"iopub.status.idle\":\"2026-08-27T07:02:40.390367Z\",\"shell.execute_reply.started\":\"2026-08-27T07:02:40.384648Z\",\"shell.execute_reply\":\"2026-08-27T07:02:40.389383Z\"}}\nimport sys\n\nREPO_PATH = \"/kaggle/working/ClauseLens\"\n\nif REPO_PATH not in sys.path:\n    sys.path.insert(0, REPO_PATH)\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2026-08-27T07:03:08.567667Z\",\"iopub.execute_input\":\"2026-08-27T07:03:08.568219Z\",\"iopub.status.idle\":\"2026-08-27T07:03:20.238118Z\",\"shell.execute_reply.started\":\"2026-08-27T07:03:08.568181Z\",\"shell.execute_reply\":\"2026-08-27T07:03:20.236776Z\"}}\n# ============================================================\n# CLAUSELENS — NODE 2 DEPENDENCIES\n# ============================================================\n\nimport sys\nimport subprocess\n\npackages = [\n    \"numpy\",\n    \"sentence-transformers\",\n    \"faiss-cpu\",\n    \"rank-bm25\",\n    \"networkx\",\n    \"pymupdf\",\n]\n\nprint(\"Installing ClauseLens Node 2 dependencies...\\n\")\n\nsubprocess.check_call([\n    sys.executable,\n    \"-m\",\n    \"pip\",\n    \"install\",\n    \"-q\",\n    *packages,\n])\n\nprint(\"\\nAll dependencies installed successfully.\")\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2026-08-27T07:03:25.753181Z\",\"iopub.execute_input\":\"2026-08-27T07:03:25.753544Z\",\"iopub.status.idle\":\"2026-08-27T07:04:12.574955Z\",\"shell.execute_reply.started\":\"2026-08-27T07:03:25.753506Z\",\"shell.execute_reply\":\"2026-08-27T07:04:12.573816Z\"}}\nfrom nodes.node_2 import (\n    prepare_chunks,\n    Node2Indexer,\n    IndexBundle,\n    semantic_search,\n    keyword_search,\n    graph_entity_search,\n    graph_multi_entity_search,\n    hybrid_search,\n)\n\nprint(\"Node 2 public API import: SUCCESS\")\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2026-08-27T07:04:15.001677Z\",\"iopub.execute_input\":\"2026-08-27T07:04:15.004722Z\",\"iopub.status.idle\":\"2026-08-27T07:04:15.018093Z\",\"shell.execute_reply.started\":\"2026-08-27T07:04:15.004554Z\",\"shell.execute_reply\":\"2026-08-27T07:04:15.016412Z\"}}\nprint(\"prepare_chunks      :\", callable(prepare_chunks))\nprint(\"Node2Indexer        :\", Node2Indexer)\nprint(\"IndexBundle         :\", IndexBundle)\nprint(\"semantic_search     :\", callable(semantic_search))\nprint(\"keyword_search      :\", callable(keyword_search))\nprint(\"graph_entity_search :\", callable(graph_entity_search))\nprint(\"graph_multi_entity  :\", callable(graph_multi_entity_search))\nprint(\"hybrid_search       :\", callable(hybrid_search))\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2026-08-27T06:44:45.328535Z\",\"iopub.execute_input\":\"2026-08-27T06:44:45.329504Z\",\"iopub.status.idle\":\"2026-08-27T06:44:45.343678Z\",\"shell.execute_reply.started\":\"2026-08-27T06:44:45.329471Z\",\"shell.execute_reply\":\"2026-08-27T06:44:45.342770Z\"}}\nfrom nodes.node_1 import (\n    extract_lines,\n    process_document,\n    process_documents,\n)\n\nprint(\"Node 1 import: SUCCESS\")\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2026-08-27T06:45:15.288410Z\",\"iopub.execute_input\":\"2026-08-27T06:45:15.289131Z\",\"iopub.status.idle\":\"2026-08-27T06:45:15.559323Z\",\"shell.execute_reply.started\":\"2026-08-27T06:45:15.289098Z\",\"shell.execute_reply\":\"2026-08-27T06:45:15.558488Z\"}}\nDoc1 = \"/kaggle/input/datasets/glassuchan/cuadtestdataset/ATHENSBANCSHARESCORP_11_02_2009-EX-1.2-AGENCY AGREEMENT  2009.PDF\"\nDoc2 = \"/kaggle/input/datasets/glassuchan/cuadtestdataset/CreditcardscomInc_20070810_S-1_EX-10.33_362297_EX-10.33_Affiliate Agreement.pdf\"\nresult = process_documents(Doc1, Doc2)\n\nprint(\"Node 1 execution: SUCCESS\")\n\nfor name, document in result.items():\n    print(\"=\" * 70)\n    print(name)\n    print(\"Lines:\", document[\"element_count\"])\n    print(\"Chunks:\", document[\"chunk_count\"])\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2026-08-27T06:47:27.287972Z\",\"iopub.execute_input\":\"2026-08-27T06:47:27.288312Z\",\"iopub.status.idle\":\"2026-08-27T06:47:32.620193Z\",\"shell.execute_reply.started\":\"2026-08-27T06:47:27.288283Z\",\"shell.execute_reply\":\"2026-08-27T06:47:32.619233Z\"}}\n# ============================================================\n# CLAUSELENS — NODE 2 DEPENDENCIES\n# ============================================================\n\nimport sys\nimport subprocess\n\npackages = [\n    \"numpy\",\n    \"sentence-transformers\",\n    \"faiss-cpu\",\n    \"rank-bm25\",\n    \"networkx\",\n    \"pymupdf\",\n]\n\nprint(\"Installing ClauseLens Node 2 dependencies...\\n\")\n\nsubprocess.check_call([\n    sys.executable,\n    \"-m\",\n    \"pip\",\n    \"install\",\n    \"-q\",\n    *packages,\n])\n\nprint(\"\\nAll dependencies installed successfully.\")\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2026-08-27T06:48:32.926447Z\",\"iopub.execute_input\":\"2026-08-27T06:48:32.927043Z\",\"iopub.status.idle\":\"2026-08-27T06:49:17.078897Z\",\"shell.execute_reply.started\":\"2026-08-27T06:48:32.927011Z\",\"shell.execute_reply\":\"2026-08-27T06:49:17.078086Z\"}}\n# ============================================================\n# NODE 2 — COMPLETE END-TO-END TEST\n# ============================================================\n\nfrom nodes.node_2.chunks import prepare_chunks\nfrom nodes.node_2.indexer import Node2Indexer\nfrom nodes.node_2.retrieval import (\n    semantic_search,\n    keyword_search,\n    graph_multi_entity_search,\n    hybrid_search,\n)\n\n\n# ============================================================\n# 1. PREPARE STRUCTURED CHUNKS\n# ============================================================\n\nall_chunks = prepare_chunks(\n    result,\n    version_ids={\n        \"document_a\": \"version_a\",\n        \"document_b\": \"version_b\",\n    },\n)\n\nprint(\"=\" * 70)\nprint(\"NODE 2 END-TO-END TEST\")\nprint(\"=\" * 70)\n\nprint(\"\\n[1] Chunk preparation\")\nprint(\"Chunks:\", len(all_chunks))\n\n\n# ============================================================\n# 2. BUILD INDEXES\n# ============================================================\n\nindexer = Node2Indexer()\n\nindex_bundle = indexer.build(\n    all_chunks\n)\n\nprint(\"\\n[2] Index construction\")\nprint(\n    \"Embeddings:\",\n    index_bundle.embeddings.shape\n)\nprint(\n    \"FAISS vectors:\",\n    index_bundle.vector_index.ntotal\n)\nprint(\n    \"BM25 documents:\",\n    len(index_bundle.tokenized_chunks)\n)\nprint(\n    \"Graph nodes:\",\n    index_bundle.knowledge_graph.number_of_nodes()\n)\nprint(\n    \"Graph edges:\",\n    index_bundle.knowledge_graph.number_of_edges()\n)\n\n\n# ============================================================\n# 3. SEMANTIC SEARCH\n# ============================================================\n\nquery = \"What are the confidentiality obligations?\"\n\nsemantic_results = semantic_search(\n    query,\n    index_bundle,\n    indexer.embedding_model,\n    top_k=3,\n)\n\nprint(\"\\n[3] Semantic search\")\nprint(\"Query:\", query)\n\nfor i, result_item in enumerate(\n    semantic_results,\n    start=1,\n):\n    print(\n        f\"{i}. \"\n        f\"{result_item['chunk_id']} | \"\n        f\"score={result_item['score']:.4f}\"\n    )\n\n\n# ============================================================\n# 4. BM25 SEARCH\n# ============================================================\n\nkeyword_results = keyword_search(\n    query,\n    index_bundle,\n    top_k=3,\n)\n\nprint(\"\\n[4] BM25 keyword search\")\nprint(\"Query:\", query)\n\nfor i, result_item in enumerate(\n    keyword_results,\n    start=1,\n):\n    print(\n        f\"{i}. \"\n        f\"{result_item['chunk_id']} | \"\n        f\"score={result_item['score']:.4f}\"\n    )\n\n\n# ============================================================\n# 5. GRAPH SEARCH\n# ============================================================\n\ngraph_results = graph_multi_entity_search(\n    \"Company\",\n    \"expenses\",\n    index_bundle,\n    top_k=10,\n)\n\nprint(\"\\n[5] Graph search\")\nprint(\n    \"Stakeholder: Company\"\n)\nprint(\n    \"Legal term : expenses\"\n)\nprint(\n    \"Matches:\",\n    len(graph_results)\n)\n\nfor result_item in graph_results:\n    print(\n        f\"- {result_item['chunk_id']}\"\n    )\n\n\n# ============================================================\n# 6. HYBRID SEARCH\n# ============================================================\n\nhybrid_query = (\n    \"What expenses must the company reimburse?\"\n)\n\nhybrid_results = hybrid_search(\n    hybrid_query,\n    index_bundle,\n    indexer.embedding_model,\n    top_k=3,\n    candidate_k=10,\n)\n\nprint(\"\\n[6] Hybrid search\")\nprint(\"Query:\", hybrid_query)\n\nfor i, result_item in enumerate(\n    hybrid_results,\n    start=1,\n):\n    print(\n        f\"{i}. \"\n        f\"{result_item['chunk_id']} | \"\n        f\"RRF={result_item['score']:.6f}\"\n    )\n\n\n# ============================================================\n# 7. BASIC VALIDATION\n# ============================================================\n\nassert len(all_chunks) == 56\n\nassert (\n    index_bundle.embeddings.shape[0]\n    == len(all_chunks)\n)\n\nassert (\n    index_bundle.vector_index.ntotal\n    == len(all_chunks)\n)\n\nassert (\n    len(index_bundle.tokenized_chunks)\n    == len(all_chunks)\n)\n\nassert len(semantic_results) > 0\n\nassert len(keyword_results) > 0\n\nassert len(graph_results) > 0\n\nassert len(hybrid_results) > 0\n\n\n# ============================================================\n# FINAL STATUS\n# ============================================================\n\nprint(\"\\n\" + \"=\" * 70)\nprint(\"NODE 2 END-TO-END TEST PASSED\")\nprint(\"=\" * 70)\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2026-08-27T06:52:23.895832Z\",\"iopub.execute_input\":\"2026-08-27T06:52:23.896570Z\",\"iopub.status.idle\":\"2026-08-27T06:52:29.051407Z\",\"shell.execute_reply.started\":\"2026-08-27T06:52:23.896532Z\",\"shell.execute_reply\":\"2026-08-27T06:52:29.050395Z\"}}\n# ============================================================\n# CLAUSELENS — NODE 2 FULL DOCUMENT TEST\n# ============================================================\n#\n# Tests the complete pipeline:\n#\n# Node 1\n#   ↓\n# chunks.py\n#   ↓\n# indexer.py\n#   ↓\n# FAISS + BM25 + NetworkX\n#   ↓\n# retrieval.py\n#\n# Both documents are processed in their entirety.\n# ============================================================\n\nfrom nodes.node_2.chunks import prepare_chunks\nfrom nodes.node_2.indexer import Node2Indexer\nfrom nodes.node_2.retrieval import (\n    semantic_search,\n    keyword_search,\n    graph_multi_entity_search,\n    hybrid_search,\n)\n\n\n# ============================================================\n# 1. PREPARE ALL CHUNKS\n# ============================================================\n\nall_chunks = prepare_chunks(\n    result,\n    version_ids={\n        \"document_a\": \"version_a\",\n        \"document_b\": \"version_b\",\n    },\n)\n\nprint(\"=\" * 80)\nprint(\"CLAUSELENS — NODE 2 FULL DOCUMENT TEST\")\nprint(\"=\" * 80)\n\nprint(\"\\n[1] NODE 1 → NODE 2\")\nprint(\"-\" * 80)\n\nprint(\"Total chunks:\", len(all_chunks))\n\n\n# ============================================================\n# 2. DOCUMENT-LEVEL CHUNK COUNT\n# ============================================================\n\ndocument_counts = {}\n\nfor chunk in all_chunks:\n\n    document_id = chunk[\"document_id\"]\n\n    document_counts[document_id] = (\n        document_counts.get(\n            document_id,\n            0,\n        )\n        + 1\n    )\n\nprint(\"\\nChunks by document:\")\n\nfor document_id, count in document_counts.items():\n\n    print(\n        f\"  {document_id}: {count} chunks\"\n    )\n\n\n# ============================================================\n# 3. BUILD COMPLETE NODE 2 INDEX\n# ============================================================\n\nprint(\"\\n[2] BUILDING NODE 2 INDEXES\")\nprint(\"-\" * 80)\n\nindexer = Node2Indexer()\n\nindex_bundle = indexer.build(\n    all_chunks\n)\n\nprint(\"\\nIndex construction complete.\")\n\nprint(\n    \"Embeddings:\",\n    index_bundle.embeddings.shape\n)\n\nprint(\n    \"FAISS vectors:\",\n    index_bundle.vector_index.ntotal\n)\n\nprint(\n    \"BM25 documents:\",\n    len(\n        index_bundle.tokenized_chunks\n    )\n)\n\nprint(\n    \"Graph nodes:\",\n    index_bundle.knowledge_graph.number_of_nodes()\n)\n\nprint(\n    \"Graph edges:\",\n    index_bundle.knowledge_graph.number_of_edges()\n)\n\n\n# ============================================================\n# 4. VERIFY INDEX ALIGNMENT\n# ============================================================\n\nprint(\"\\n[3] VERIFYING INDEX ALIGNMENT\")\nprint(\"-\" * 80)\n\ntotal_chunks = len(all_chunks)\n\nassert (\n    index_bundle.embeddings.shape[0]\n    == total_chunks\n), \"Embedding count does not match chunk count.\"\n\nassert (\n    index_bundle.vector_index.ntotal\n    == total_chunks\n), \"FAISS vector count does not match chunk count.\"\n\nassert (\n    len(index_bundle.tokenized_chunks)\n    == total_chunks\n), \"BM25 document count does not match chunk count.\"\n\nassert (\n    len(index_bundle.vector_id_to_chunk_id)\n    == total_chunks\n), \"FAISS mapping count does not match chunk count.\"\n\nassert (\n    len(index_bundle.bm25_id_to_chunk_id)\n    == total_chunks\n), \"BM25 mapping count does not match chunk count.\"\n\nprint(\"Chunk count          :\", total_chunks)\nprint(\"Embedding count      :\", index_bundle.embeddings.shape[0])\nprint(\"FAISS vector count   :\", index_bundle.vector_index.ntotal)\nprint(\"BM25 document count  :\", len(index_bundle.tokenized_chunks))\nprint(\"FAISS mapping count  :\", len(index_bundle.vector_id_to_chunk_id))\nprint(\"BM25 mapping count   :\", len(index_bundle.bm25_id_to_chunk_id))\n\nprint(\"\\nIndex alignment: PASS\")\n\n\n# ============================================================\n# 5. SEMANTIC SEARCH\n# ============================================================\n\nsemantic_query = (\n    \"What are the confidentiality obligations?\"\n)\n\nprint(\"\\n[4] SEMANTIC SEARCH\")\nprint(\"-\" * 80)\n\nprint(\"Query:\", semantic_query)\n\nsemantic_results = semantic_search(\n    semantic_query,\n    index_bundle,\n    indexer.embedding_model,\n    top_k=5,\n)\n\nassert len(semantic_results) > 0\n\nfor rank, item in enumerate(\n    semantic_results,\n    start=1,\n):\n\n    print(\n        f\"{rank}. \"\n        f\"{item['chunk_id']} | \"\n        f\"{item['document_id']} | \"\n        f\"score={item['score']:.4f}\"\n    )\n\n\n# ============================================================\n# 6. BM25 SEARCH\n# ============================================================\n\nprint(\"\\n[5] BM25 KEYWORD SEARCH\")\nprint(\"-\" * 80)\n\nprint(\"Query:\", semantic_query)\n\nkeyword_results = keyword_search(\n    semantic_query,\n    index_bundle,\n    top_k=5,\n)\n\nassert len(keyword_results) > 0\n\nfor rank, item in enumerate(\n    keyword_results,\n    start=1,\n):\n\n    print(\n        f\"{rank}. \"\n        f\"{item['chunk_id']} | \"\n        f\"{item['document_id']} | \"\n        f\"score={item['score']:.4f}\"\n    )\n\n\n# ============================================================\n# 7. GRAPH SEARCH\n# ============================================================\n\nprint(\"\\n[6] GRAPH SEARCH\")\nprint(\"-\" * 80)\n\nprint(\"Stakeholder: Company\")\nprint(\"Legal term : expenses\")\n\ngraph_results = graph_multi_entity_search(\n    \"Company\",\n    \"expenses\",\n    index_bundle,\n    top_k=20,\n)\n\nassert len(graph_results) > 0\n\nprint(\n    \"Matching chunks:\",\n    len(graph_results)\n)\n\nfor item in graph_results:\n\n    print(\n        f\"- \"\n        f\"{item['chunk_id']} | \"\n        f\"{item['document_id']} | \"\n        f\"pages \"\n        f\"{item['page_start']}-\"\n        f\"{item['page_end']}\"\n    )\n\n\n# ============================================================\n# 8. HYBRID SEARCH\n# ============================================================\n\nhybrid_query = (\n    \"What expenses must the company reimburse?\"\n)\n\nprint(\"\\n[7] HYBRID SEARCH\")\nprint(\"-\" * 80)\n\nprint(\"Query:\", hybrid_query)\n\nhybrid_results = hybrid_search(\n    hybrid_query,\n    index_bundle,\n    indexer.embedding_model,\n    top_k=5,\n    candidate_k=10,\n)\n\nassert len(hybrid_results) > 0\n\nfor rank, item in enumerate(\n    hybrid_results,\n    start=1,\n):\n\n    print(\n        f\"{rank}. \"\n        f\"{item['chunk_id']} | \"\n        f\"{item['document_id']} | \"\n        f\"RRF={item['score']:.6f}\"\n    )\n\n\n# ============================================================\n# 9. VERIFY RESULTS POINT TO REAL CHUNKS\n# ============================================================\n\nprint(\"\\n[8] VERIFYING RETRIEVAL MAPPINGS\")\nprint(\"-\" * 80)\n\nvalid_chunk_ids = {\n    chunk[\"chunk_id\"]\n    for chunk in all_chunks\n}\n\nall_retrieval_results = (\n    semantic_results\n    + keyword_results\n    + graph_results\n    + hybrid_results\n)\n\nfor item in all_retrieval_results:\n\n    assert (\n        item[\"chunk_id\"]\n        in valid_chunk_ids\n    ), (\n        \"Retrieval returned an unknown \"\n        f\"chunk ID: {item['chunk_id']}\"\n    )\n\nprint(\n    \"All retrieved chunk IDs correspond \"\n    \"to canonical Node 2 chunks.\"\n)\n\nprint(\"Retrieval mapping: PASS\")\n\n\n# ============================================================\n# 10. VERIFY BOTH DOCUMENTS ARE INDEXED\n# ============================================================\n\nprint(\"\\n[9] VERIFYING DOCUMENT COVERAGE\")\nprint(\"-\" * 80)\n\nindexed_documents = {\n    chunk[\"document_id\"]\n    for chunk in index_bundle.chunks\n}\n\nprint(\n    \"Indexed documents:\",\n    sorted(indexed_documents)\n)\n\nassert \"document_a\" in indexed_documents\nassert \"document_b\" in indexed_documents\n\nprint(\"document_a: PASS\")\nprint(\"document_b: PASS\")\n\n\n# ============================================================\n# 11. FINAL SUMMARY\n# ============================================================\n\nprint(\"\\n\" + \"=\" * 80)\nprint(\"NODE 2 FULL DOCUMENT TEST PASSED\")\nprint(\"=\" * 80)\n\nprint(\"\\nDocuments processed :\", len(indexed_documents))\nprint(\"Total chunks        :\", total_chunks)\nprint(\n    \"Embeddings          :\",\n    index_bundle.embeddings.shape,\n)\nprint(\n    \"FAISS vectors       :\",\n    index_bundle.vector_index.ntotal,\n)\nprint(\n    \"BM25 documents      :\",\n    len(index_bundle.tokenized_chunks),\n)\nprint(\n    \"Graph nodes         :\",\n    index_bundle.knowledge_graph.number_of_nodes(),\n)\nprint(\n    \"Graph edges         :\",\n    index_bundle.knowledge_graph.number_of_edges(),\n)\n\nprint(\"\\nRetrieval tests:\")\nprint(\"  Semantic : PASS\")\nprint(\"  BM25     : PASS\")\nprint(\"  Graph    : PASS\")\nprint(\"  Hybrid   : PASS\")\n\nprint(\"\\n\" + \"=\" * 80)\nprint(\"ALL NODE 2 TESTS PASSED\")\nprint(\"=\" * 80)\n\n# %% [code]\n","metadata":{"_uuid":"c0cbe873-6069-4f38-9a3c-8064686bb94c","_cell_guid":"371c4835-2f80-4ddf-b88b-a634d593a38b","trusted":true,"collapsed":false,"jupyter":{"outputs_hidden":false}},"outputs":[],"execution_count":null}]}